 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    boxes = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if not (all(grid[r0][c] == color for c in range(c0, c1 + 1)) and
                all(grid[r1][c] == color for c in range(c0, c1 + 1)) and
                all(grid[r][c0] == color for r in range(r0, r1 + 1)) and
                all(grid[r][c1] == color for r in range(r0, r1 + 1))):
            continue
        interior = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                    for r in range(r0 + 1, r1)]
        boxes.append([color, r0, r1, c0, c1, interior])

    sources = [b for b in boxes if any(any(row) for row in b[5])]
    if not sources:
        return out
    color, r0, r1, c0, c1, pattern = sources[0]

    # A solid interior line adjoining the frame is part of its border, not the
    # transferred motif (as in a motif touching the bottom edge of its frame).
    while pattern and pattern[0] and all(pattern[0]):
        pattern = pattern[1:]
    while pattern and pattern[-1] and all(pattern[-1]):
        pattern = pattern[:-1]
    while pattern and pattern[0] and all(row[0] for row in pattern):
        pattern = [row[1:] for row in pattern]
    while pattern and pattern[0] and all(row[-1] for row in pattern):
        pattern = [row[:-1] for row in pattern]
    target_h, target_w = len(pattern) + 2, (len(pattern[0]) if pattern else 0) + 2

    for other, a, b, x, y, _ in boxes:
        if other == color:
            continue
        if b - a + 1 == target_h and y - x + 1 == target_w:
            for rr in range(a + 1, b):
                for cc in range(x + 1, y):
                    pr, pc = rr - a - 1, cc - x - 1
                    out[rr][cc] = other if pr < len(pattern) and pc < len(pattern[0]) and pattern[pr][pc] else 0
        else:
            for rr in range(a, b + 1):
                for cc in range(x, y + 1):
                    out[rr][cc] = 0
    return out
